using System.Linq;
using System.Text;
using Fanex.Age.Utility.NPOI;
using NPOI.HSSF.UserModel;
using NPOI.SS.UserModel;
using Sunplus.Agent.Model.Entities.Permission;
using Sunplus.Agent.Utilities;

namespace Fanex.Age.Excel.Reports.Commission
{
    internal class CommissionByBetTypeReport : TemplateReport, IReportBuilder
    {
        private CommissionByBetTypeReportBuilder _builder;

        public CommissionByBetTypeReport(string filePath, CommissionByBetTypeReportBuilder builder)
            : base(filePath)
        {
            _builder = builder;
        }

        public HSSFWorkbook Build()
        {
            var data = _builder.Data;
            if (data == null) return null;

            ISheet templateSheet = hssfWorkbook.GetSheet("Template");
            ISheet resultSheet = hssfWorkbook.GetSheet("CommissionByBetType");
            // apply Bold on all fonts
            if (_builder.IsBold)
            {
                BoldAllFonts();
            }

            int rowIdContent = 3;
            int rowId = 0;
            int colId = 0;
            hssfWorkbook.SetSheetName(0, Resources.Lang.lblCommissionByBettype);

            // header
            short totalColumn = 41;
            short totalRemoveColumn = 0;
            if (!UserPermission.IsShowCasino)
            {
                totalRemoveColumn++;
            }
            if (!UserPermission.IsShowLiveCasino)
            {
                totalRemoveColumn++;
            }
            if (!UserPermission.IsShowNumberGame)
            {
                totalRemoveColumn++;
            }
            if (!(UserPermission.IsShowBingo && !Sunplus.Agent.Model.BL.Definitions.AppSettings.DisabledBingoCommission))
            {
                totalRemoveColumn++;
            }
            if (!UserPermission.IsShowP2P)
            {
                totalRemoveColumn++;
            }
            if (!UserPermission.EnableKeno)
            {
                totalRemoveColumn++;
            }
            for (int i = 0; i < totalRemoveColumn; i++)
            {
                resultSheet.RemoveColumn((short)(totalColumn - (i + 1)));
            }

            string currentUserType = "";
            if (_builder.RoleId == (int)(Sunplus.Agent.Model.BL.Definitions.UserTypes.Super))
            {
                currentUserType = Resources.Lang.superCommissionByBetType;
            }
            else if (_builder.RoleId == (int)(Sunplus.Agent.Model.BL.Definitions.UserTypes.Master))
            {
                currentUserType = Resources.Lang.masterCommissionByBetType;
            }
            else
            {
                currentUserType = Resources.Lang.agentCommissionByBetType;
            }

            resultSheet.GetCell(rowId, colId).SetCellValue(currentUserType + " " +
                Formater.ShortDateFormat(_builder.FromDate) + "-->" + Formater.ShortDateFormat(_builder.ToDate));
            rowId = 1;

            var values = new List<object>{Resources.Lang.username,
                Resources.Lang.commission + " 1", "", "", "", "", "", "", "", "", "", "", "", "", "",
                Resources.Lang.commission + " 2", "", "",
                Resources.Lang.commission + " 3", "", "", "", "", "", "", "", "", "", "", "", "", "", "",
                Resources.Lang.OtherBettypes,
                Resources.Lang.games};

            resultSheet.GetRow(rowId).WriteCells(colId, values);

            rowId = 2;
            values = new List<object>{
                Resources.Lang.lbl1stHdp,
                Resources.Lang.hdp,
                Resources.Lang.lbl1stOU,
                Resources.Lang.lblOU,
                Resources.Lang.lbl1stOE,
                Resources.Lang.lblOE,
                Resources.Lang.CSheet,
                Resources.Lang.DNB,
                Resources.Lang.HNB,
                Resources.Lang.ANB,
                Resources.Lang.DND,
                Resources.Lang.TWinTNill,
                Resources.Lang.ThirdWayHdp,
                Resources.Lang.total,
                Resources.Lang.lbl1x2_1st,
                Resources.Lang.lbl1x2,
                Resources.Lang.total,
                Resources.Lang.lbl1stCS,
                Resources.Lang.lblCS,
                Resources.Lang.lbl1stTG,
                Resources.Lang.lblTG,
                Resources.Lang.lblMP,
                Resources.Lang.lblSP,
                Resources.Lang.lblOutRight,
                Resources.Lang.lbl1stFGLG,
                Resources.Lang.fglg,
                Resources.Lang.htft,
                Resources.Lang.moneyline,
                Resources.Lang.lbl1stMoneyLine,
                Resources.Lang.DChance,
                Resources.Lang.BON,
                Resources.Lang.total,
                string.Empty
            };

            if (UserPermission.IsShowCasino)
            {
                values.Add(Resources.Lang.casino);
            }
            if (UserPermission.IsShowLiveCasino)
            {
                values.Add(Resources.Lang.LiveCasino);
            }
            if (UserPermission.IsShowNumberGame)
            {
                values.Add(Resources.Lang.numbergame);
            }
            if (UserPermission.IsShowBingo && !Sunplus.Agent.Model.BL.Definitions.AppSettings.DisabledBingoCommission)
            {
                values.Add(Resources.Lang.bingo);
            }
            if (UserPermission.IsShowP2P)
            {
                values.Add(Resources.Lang.P2P);
            }
            if (UserPermission.EnableKeno)
            {
                values.Add(Resources.Lang.Keno);
            }

            values.Add(Resources.Lang.total);
            resultSheet.GetRow(rowId).WriteCells(colId + 1, values);

            // content
            rowId = rowIdContent;
            int id = 1;
            var totalGame = 0m;

            if (data.Count > 0)
            {
                int lastColumnIndex = colId + totalColumn - totalRemoveColumn - 1;

                foreach (var item in data)
                {
                    var sumGame = 0m;

                    if (id % 2 == 0)
                    {
                        resultSheet.CopyRow(templateSheet, 1, rowId, colId, lastColumnIndex);
                    }
                    else
                    {
                        resultSheet.CopyRow(templateSheet, 3, rowId, colId, lastColumnIndex);
                    }
                    values = new List<object> { item.Username, item.FirstHalfHandicap, item.Handicap, item.FirstHalfOverUnder, item.OverUnder, 
                        item.FirstHalfOddEven, item.OddEven, item.CSheet, item.DNB, item.HNB, item.ANB, item.DND, item.TWinTNill, item.ThirdWayHdp, item.Total1,
                        item.First1X2Comm, item.OneXTwoComm, item.Total2,
                        item.FirstCS, item.CorrectScore, item.FirstHalfTotalGoal, item.TotalGoal, item.MixParlay, item.CombinationMixParlay, item.Outright,
                        item.FirstHalfFGLG, item.FGLG, item.HTFT, item.MoneyLineFullTime, item.MoneyLineHalfTime, item.DChance, item.BON, item.Total3, item.Others};
                    if (UserPermission.IsShowCasino)
                    {
                        values.Add(item.Casino);
                        sumGame += item.Casino;
                    }
                    if (UserPermission.IsShowLiveCasino)
                    {
                        values.Add(item.LiveCasino);
                        sumGame += item.LiveCasino;
                    }
                    if (UserPermission.IsShowNumberGame)
                    {
                        values.Add(item.NumberGame);
                        sumGame += item.NumberGame;
                    }
                    if (UserPermission.IsShowBingo && !Sunplus.Agent.Model.BL.Definitions.AppSettings.DisabledBingoCommission)
                    {
                        values.Add(item.Bingo);
                        sumGame += item.Bingo;
                    }
                    if (UserPermission.IsShowP2P)
                    {
                        values.Add(item.P2P);
                        sumGame += item.P2P;
                    }
                    if (UserPermission.EnableKeno)
                    {
                        values.Add(item.Keno);
                        sumGame += item.Keno;
                    }

                    totalGame += sumGame;

                    values.Add(sumGame);

                    resultSheet.GetRow(rowId).WriteCells(colId, values);

                    id++;
                    rowId++;
                }

                // total
                resultSheet.CopyRow(templateSheet, 5, rowId, colId, lastColumnIndex);
                values = new List<object> {Resources.Lang.total,
                    data.Sum(p => p.FirstHalfHandicap), data.Sum(p => p.Handicap), data.Sum(p => p.FirstHalfOverUnder), data.Sum(p => p.OverUnder), 
                    data.Sum(p => p.FirstHalfOddEven), data.Sum(p => p.OddEven), data.Sum(p => p.CSheet), data.Sum(p => p.DNB),
                    data.Sum(p => p.HNB), data.Sum(p => p.ANB), data.Sum(p => p.DND),
                    data.Sum(p => p.TWinTNill), data.Sum(p => p.ThirdWayHdp), data.Sum(p => p.Total1),
                    data.Sum(p => p.First1X2Comm), data.Sum(p => p.OneXTwoComm), data.Sum(p => p.Total2),
                    data.Sum(p => p.FirstCS), data.Sum(p => p.CorrectScore), data.Sum(p => p.FirstHalfTotalGoal), data.Sum(p => p.TotalGoal),
                    data.Sum(p => p.MixParlay), data.Sum(p => p.CombinationMixParlay), data.Sum(p => p.Outright),
                    data.Sum(p => p.FirstHalfFGLG), data.Sum(p => p.FGLG), data.Sum(p => p.HTFT), data.Sum(p => p.MoneyLineFullTime),
                    data.Sum(p => p.MoneyLineHalfTime), data.Sum(p => p.DChance), data.Sum(p => p.BON), data.Sum(p => p.Total3) };

                values.Add(data.Sum(p => p.Others));

                if (UserPermission.IsShowCasino)
                {
                    values.Add(data.Sum(p => p.Casino));
                }
                if (UserPermission.IsShowLiveCasino)
                {
                    values.Add(data.Sum(p => p.LiveCasino));
                }
                if (UserPermission.IsShowNumberGame)
                {
                    values.Add(data.Sum(p => p.NumberGame));
                }
                if (UserPermission.IsShowBingo && !Sunplus.Agent.Model.BL.Definitions.AppSettings.DisabledBingoCommission)
                {
                    values.Add(data.Sum(p => p.Bingo));
                }
                if (UserPermission.IsShowP2P)
                {
                    values.Add(data.Sum(p => p.P2P));
                }
                if (UserPermission.EnableKeno)
                {
                    values.Add(data.Sum(p => p.Keno));
                }

                values.Add(totalGame);

                resultSheet.GetRow(rowId).WriteCells(colId, values);

                //Thai@20140422: Make Bold for last "Total" column
                IFont font = hssfWorkbook.CreateFont();
                font.Boldweight = (short)FontBoldWeight.Bold;
                font.FontName = "Tahoma";
                font.FontHeightInPoints = 9;

                rowId--;
                while (rowId >= rowIdContent)
                {                    
                    ICell besideCell = resultSheet.GetCell(rowId, lastColumnIndex - 1);
                    
                    ICellStyle newCellStyle = hssfWorkbook.CreateCellStyle();
                    newCellStyle.CloneStyleFrom(besideCell.CellStyle);
                    newCellStyle.SetFont(font);

                    resultSheet.GetCell(rowId, lastColumnIndex).CellStyle = newCellStyle;
                    
                    rowId--;
                }
                //End Make Bold
            }

            hssfWorkbook.RemoveSheetAt(hssfWorkbook.GetSheetIndex(templateSheet));
            return hssfWorkbook;
        }
    }
}